//! `librosa.sequence`, `librosa.segment` and `librosa.util.sync` references
//! (fixture `sequence.json`, generated by `cases/sequence.py`).
//!
//! The inputs are stored in the fixture, so every case is the same
//! computation on bit-identical inputs. Dynamic-programming outputs (DTW
//! accumulated costs, Viterbi log-likelihoods, RQA scores) are sums of the
//! same terms in the same order as librosa's numba kernels; the only
//! round-off sources are the local costs (scipy's `cdist` / numpy's `log`
//! may differ from ours by an ulp), so they are compared at `1e-12`
//! relative to the matrix peak. Paths and state sequences must match exactly.

use audio_samples::operations::sequence::{
    Bandwidth, CrossSimilarityConfig, DistanceMetric, DtwConfig, RecurrenceConfig, RecurrenceMode,
    RqaConfig, SyncAggregate, TransitionWindow, cross_similarity, dtw, dtw_backtracking,
    dtw_with_cost, lag_to_recurrence, recurrence_matrix, recurrence_to_lag, rqa, sync,
    transition_cycle, transition_local, transition_loop, transition_uniform, viterbi,
    viterbi_binary, viterbi_discriminative,
};
use ndarray::{Array1, Array2, Array3};
use serde_json::Value;

use crate::common::{arr1, arr2, arr3, assert_close, errors, load};

/// Exact algorithm, identical summation order; only ulp-level differences in
/// the local cost / log terms (see module docs).
const RTOL_DP: f64 = 1e-12;

fn fixture() -> Value {
    load("sequence")
}

/// 2-D array where `null` encodes +inf (DTW accumulated costs).
fn arr2_inf(v: &Value) -> Array2<f64> {
    let rows: Vec<Vec<f64>> = v
        .as_array()
        .expect("2-D array")
        .iter()
        .map(|r| {
            r.as_array()
                .expect("row")
                .iter()
                .map(|x| x.as_f64().unwrap_or(f64::INFINITY))
                .collect()
        })
        .collect();
    let (r, c) = (rows.len(), rows.first().map_or(0, Vec::len));
    Array2::from_shape_vec((r, c), rows.into_iter().flatten().collect()).expect("rectangular")
}

fn usize_vec(v: &Value) -> Vec<usize> {
    v.as_array()
        .expect("array")
        .iter()
        .map(|x| x.as_u64().expect("non-negative integer") as usize)
        .collect()
}

fn usize2(v: &Value) -> Array2<usize> {
    let rows: Vec<Vec<usize>> = v.as_array().expect("2-D").iter().map(usize_vec).collect();
    let (r, c) = (rows.len(), rows.first().map_or(0, Vec::len));
    Array2::from_shape_vec((r, c), rows.into_iter().flatten().collect()).expect("rectangular")
}

fn pairs(v: &Value) -> Vec<[usize; 2]> {
    v.as_array()
        .expect("path")
        .iter()
        .map(|p| {
            let p = usize_vec(p);
            [p[0], p[1]]
        })
        .collect()
}

fn opt_arr1(v: &Value) -> Option<Array1<f64>> {
    (!v.is_null()).then(|| arr1(v))
}

/// Compare matrices that may contain +inf: the inf patterns must agree
/// exactly and the finite entries within `RTOL_DP` of the finite peak.
#[track_caller]
fn assert_cost_matrix(what: &str, actual: &Array2<f64>, expected: &Array2<f64>) {
    assert_eq!(actual.dim(), expected.dim(), "{what}: shape");
    for (a, e) in actual.iter().zip(expected) {
        assert_eq!(a.is_infinite(), e.is_infinite(), "{what}: inf pattern");
    }
    let fa: Vec<f64> = actual.iter().copied().filter(|v| v.is_finite()).collect();
    let fe: Vec<f64> = expected.iter().copied().filter(|v| v.is_finite()).collect();
    assert_close(what, &fa, &fe, RTOL_DP, 0.0);
}

fn metric(name: &str) -> DistanceMetric {
    match name {
        "euclidean" => DistanceMetric::Euclidean,
        "sqeuclidean" => DistanceMetric::SqEuclidean,
        "cosine" => DistanceMetric::Cosine,
        "cityblock" => DistanceMetric::Cityblock,
        "chebyshev" => DistanceMetric::Chebyshev,
        other => panic!("unknown metric {other}"),
    }
}

fn dtw_config(cfg: &Value) -> DtwConfig {
    let mut c = DtwConfig::librosa();
    if let Some(m) = cfg.get("metric") {
        c.metric = metric(m.as_str().unwrap());
    }
    if let Some(s) = cfg.get("step_sizes_sigma") {
        c.step_sizes_sigma = Some(usize2(s).rows().into_iter().map(|r| [r[0], r[1]]).collect());
    }
    if let Some(w) = cfg.get("weights_add") {
        c.weights_add = Some(arr1(w).to_vec());
    }
    if let Some(w) = cfg.get("weights_mul") {
        c.weights_mul = Some(arr1(w).to_vec());
    }
    if let Some(v) = cfg.get("subseq") {
        c.subseq = v.as_bool().unwrap();
    }
    if let Some(v) = cfg.get("global_constraints") {
        c.global_constraints = v.as_bool().unwrap();
    }
    if let Some(v) = cfg.get("band_rad") {
        c.band_rad = v.as_f64().unwrap();
    }
    c
}

#[test]
fn dtw_matches_librosa() {
    let f = fixture();
    let inputs = &f["dtw"]["inputs"];
    let cases = f["dtw"]["cases"].as_object().unwrap();
    assert!(cases.len() >= 18);
    for (name, case) in cases {
        let cfg = dtw_config(&case["config"]);
        let r = if let Some(c) = case.get("C") {
            dtw_with_cost(arr2(&inputs[c.as_str().unwrap()]).view(), &cfg)
        } else {
            let x = arr2(&inputs[case["X"].as_str().unwrap()]);
            let y = arr2(&inputs[case["Y"].as_str().unwrap()]);
            dtw(x.view(), y.view(), &cfg)
        }
        .unwrap_or_else(|e| panic!("{name}: {e}"));
        let d = arr2_inf(&case["D"]);
        assert_cost_matrix(&format!("dtw/{name}: D"), &r.cost, &d);
        assert_eq!(r.steps, usize2(&case["steps"]), "dtw/{name}: steps");
        assert_eq!(r.path.unwrap(), pairs(&case["wp"]), "dtw/{name}: path");
        let fa: Vec<f64> = r.cost.iter().copied().filter(|v| v.is_finite()).collect();
        let fe: Vec<f64> = d.iter().copied().filter(|v| v.is_finite()).collect();
        let (abs, rel) = errors(&fa, &fe);
        eprintln!("dtw/{name}: max abs {abs:.2e}, rel {rel:.2e}");
    }
}

#[test]
fn dtw_backtracking_matches_librosa() {
    let f = fixture();
    for (name, case) in f["dtw_backtracking"].as_object().unwrap() {
        let steps = usize2(&case["steps"]);
        let sigma: Option<Vec<[usize; 2]>> = (!case["step_sizes_sigma"].is_null()).then(|| {
            usize2(&case["step_sizes_sigma"])
                .rows()
                .into_iter()
                .map(|r| [r[0], r[1]])
                .collect()
        });
        let start = case["start"].as_u64().map(|s| s as usize);
        let wp = dtw_backtracking(
            steps.view(),
            sigma.as_deref(),
            case["subseq"].as_bool().unwrap(),
            start,
        )
        .unwrap();
        assert_eq!(wp, pairs(&case["wp"]), "dtw_backtracking/{name}");
    }
}

fn min_prob(case: &Value) -> Option<f64> {
    case["min_prob"].as_f64()
}

#[test]
fn viterbi_matches_librosa() {
    let f = fixture();
    for (name, case) in f["viterbi"].as_object().unwrap() {
        let p_init = opt_arr1(&case["p_init"]);
        let r = viterbi(
            arr2(&case["prob"]).view(),
            arr2(&case["transition"]).view(),
            p_init.as_ref().map(|p| p.view()),
            min_prob(case),
        )
        .unwrap();
        assert_eq!(
            r.states,
            usize_vec(&case["states"]),
            "viterbi/{name}: states"
        );
        let e = case["logp"].as_f64().unwrap();
        assert_close(
            &format!("viterbi/{name}: logp"),
            &[r.log_prob],
            &[e],
            RTOL_DP,
            0.0,
        );
        eprintln!(
            "viterbi/{name}: logp abs err {:.2e}",
            (r.log_prob - e).abs()
        );
    }
    for (name, case) in f["viterbi_discriminative"].as_object().unwrap() {
        let p_state = opt_arr1(&case["p_state"]);
        let p_init = opt_arr1(&case["p_init"]);
        let r = viterbi_discriminative(
            arr2(&case["prob"]).view(),
            arr2(&case["transition"]).view(),
            p_state.as_ref().map(|p| p.view()),
            p_init.as_ref().map(|p| p.view()),
            min_prob(case),
        )
        .unwrap();
        assert_eq!(
            r.states,
            usize_vec(&case["states"]),
            "discriminative/{name}"
        );
        let e = case["logp"].as_f64().unwrap();
        assert_close(
            &format!("discriminative/{name}: logp"),
            &[r.log_prob],
            &[e],
            RTOL_DP,
            0.0,
        );
        eprintln!(
            "discriminative/{name}: logp abs err {:.2e}",
            (r.log_prob - e).abs()
        );
    }
    for (name, case) in f["viterbi_binary"].as_object().unwrap() {
        let p_state = opt_arr1(&case["p_state"]);
        let p_init = opt_arr1(&case["p_init"]);
        let trans: Array3<f64> = arr3(&case["transition"]);
        let r = viterbi_binary(
            arr2(&case["prob"]).view(),
            trans.view(),
            p_state.as_ref().map(|p| p.view()),
            p_init.as_ref().map(|p| p.view()),
            min_prob(case),
        )
        .unwrap();
        assert_eq!(r.states, usize2(&case["states"]), "binary/{name}: states");
        let e = arr1(&case["logp"]);
        assert_close(
            &format!("binary/{name}: logp"),
            &r.log_prob,
            &e,
            RTOL_DP,
            0.0,
        );
        eprintln!("binary/{name}: logp {:?}", errors(&r.log_prob, &e));
    }
}

#[test]
fn transitions_match_librosa() {
    let f = fixture();
    for (name, case) in f["transition"].as_object().unwrap() {
        let a = &case["args"];
        let n = a["n"].as_u64().unwrap() as usize;
        let t = match a["kind"].as_str().unwrap() {
            "uniform" => transition_uniform(n),
            "loop" => transition_loop(n, &arr1(&a["prob"]).to_vec()),
            "cycle" => transition_cycle(n, &arr1(&a["prob"]).to_vec()),
            "local" => {
                let window = match a["window"].as_str().unwrap() {
                    "triangle" => TransitionWindow::Triangle,
                    "hann" => TransitionWindow::Hann,
                    "hamming" => TransitionWindow::Hamming,
                    "blackman" => TransitionWindow::Blackman,
                    "boxcar" => TransitionWindow::Boxcar,
                    w => panic!("unknown window {w}"),
                };
                transition_local(
                    n,
                    &usize_vec(&a["width"]),
                    window,
                    a["wrap"].as_bool().unwrap(),
                )
            }
            k => panic!("unknown kind {k}"),
        }
        .unwrap_or_else(|e| panic!("{name}: {e}"));
        // Same closed-form window values and normalisation as scipy/librosa;
        // the cosine windows may differ from numpy's `cos` by an ulp.
        assert_close(
            &format!("transition/{name}"),
            &t,
            &arr2(&case["T"]),
            1e-15,
            0.0,
        );
    }
}

#[test]
fn rqa_matches_librosa() {
    let f = fixture();
    let sims = &f["rqa"]["sims"];
    for (name, case) in f["rqa"]["cases"].as_object().unwrap() {
        let sim = arr2(&sims[case["sim"].as_str().unwrap()]);
        let cfg = RqaConfig::librosa()
            .with_gap_onset(case["gap_onset"].as_f64().unwrap())
            .with_gap_extend(case["gap_extend"].as_f64().unwrap())
            .with_knight_moves(case["knight_moves"].as_bool().unwrap());
        let r = rqa(sim.view(), &cfg).unwrap();
        // Same additions/subtractions in the same order; numba's compiled
        // kernel still differs by an ulp in a few affinity cells.
        let e = arr2(&case["score"]);
        assert_close(&format!("rqa/{name}: score"), &r.score, &e, 1e-15, 0.0);
        eprintln!("rqa/{name}: {:?}", errors(&r.score, &e));
        assert_eq!(r.path.unwrap(), pairs(&case["path"]), "rqa/{name}: path");
    }
}

fn bandwidth(v: Option<&Value>) -> Bandwidth {
    match v {
        None => Bandwidth::MedKScalar,
        Some(Value::String(s)) => match s.as_str() {
            "med_k_scalar" => Bandwidth::MedKScalar,
            "mean_k" => Bandwidth::MeanK,
            "gmean_k" => Bandwidth::GmeanK,
            "mean_k_avg" => Bandwidth::MeanKAvg,
            "gmean_k_avg" => Bandwidth::GmeanKAvg,
            "mean_k_avg_and_pair" => Bandwidth::MeanKAvgAndPair,
            other => panic!("unknown bandwidth {other}"),
        },
        Some(x) => Bandwidth::Scalar(x.as_f64().unwrap()),
    }
}

fn mode(v: Option<&Value>) -> RecurrenceMode {
    match v.and_then(Value::as_str) {
        None | Some("connectivity") => RecurrenceMode::Connectivity,
        Some("distance") => RecurrenceMode::Distance,
        Some("affinity") => RecurrenceMode::Affinity,
        Some(other) => panic!("unknown mode {other}"),
    }
}

/// Nearest-neighbour distances: librosa uses sklearn (kd-tree here, exact
/// `sqrt(sum of squares)`; brute force for cosine). Affinities additionally go
/// through `exp`. Both are ulp-level differences, but the bandwidth is a
/// median/mean of distances that feeds an exponential, so allow 1e-12.
const RTOL_KNN: f64 = 1e-12;

#[test]
fn recurrence_matrix_matches_librosa() {
    let f = fixture();
    let data = arr2(&f["segment_input"]);
    for (name, case) in f["recurrence"].as_object().unwrap() {
        let c = &case["config"];
        let cfg = RecurrenceConfig {
            k: c.get("k").and_then(Value::as_u64).map(|k| k as usize),
            width: c
                .get("width")
                .and_then(Value::as_u64)
                .map_or(1, |w| w as usize),
            metric: c
                .get("metric")
                .and_then(Value::as_str)
                .map_or(DistanceMetric::Euclidean, metric),
            sym: c.get("sym").and_then(Value::as_bool).unwrap_or(false),
            mode: mode(c.get("mode")),
            bandwidth: bandwidth(c.get("bandwidth")),
            self_links: c.get("self").and_then(Value::as_bool).unwrap_or(false),
            full: c.get("full").and_then(Value::as_bool).unwrap_or(false),
        };
        let r = recurrence_matrix(data.view(), &cfg).unwrap();
        let e = arr2(&case["R"]);
        assert_eq!(r.dim(), e.dim(), "recurrence/{name}: shape");
        let pattern_ok = r.iter().zip(&e).all(|(a, b)| (*a != 0.0) == (*b != 0.0));
        assert!(pattern_ok, "recurrence/{name}: link pattern differs");
        assert_close(&format!("recurrence/{name}"), &r, &e, RTOL_KNN, 0.0);
        eprintln!("recurrence/{name}: {:?}", errors(&r, &e));
    }
}

#[test]
fn cross_similarity_matches_librosa() {
    let f = fixture();
    let data = arr2(&f["cross_data"]);
    let reference = arr2(&f["cross_ref"]);
    for (name, case) in f["cross_similarity"].as_object().unwrap() {
        let c = &case["config"];
        let cfg = CrossSimilarityConfig {
            k: c.get("k").and_then(Value::as_u64).map(|k| k as usize),
            metric: c
                .get("metric")
                .and_then(Value::as_str)
                .map_or(DistanceMetric::Euclidean, metric),
            mode: mode(c.get("mode")),
            bandwidth: bandwidth(c.get("bandwidth")),
            full: c.get("full").and_then(Value::as_bool).unwrap_or(false),
        };
        let ref_cols = c
            .get("ref_cols")
            .and_then(Value::as_u64)
            .map_or(reference.ncols(), |n| n as usize);
        let r = cross_similarity(
            data.view(),
            reference.slice(ndarray::s![.., ..ref_cols]),
            &cfg,
        )
        .unwrap();
        let e = arr2(&case["R"]);
        assert_eq!(r.dim(), e.dim(), "cross_similarity/{name}: shape");
        let pattern_ok = r.iter().zip(&e).all(|(a, b)| (*a != 0.0) == (*b != 0.0));
        assert!(pattern_ok, "cross_similarity/{name}: link pattern differs");
        assert_close(&format!("cross_similarity/{name}"), &r, &e, RTOL_KNN, 0.0);
        eprintln!("cross_similarity/{name}: {:?}", errors(&r, &e));
    }
}

#[test]
fn lag_matches_librosa() {
    let f = fixture();
    let rec = arr2(&f["lag"]["rec"]);
    for pad in [true, false] {
        let case = &f["lag"][format!("pad_{}", if pad { "True" } else { "False" })];
        let lag = recurrence_to_lag(rec.view(), pad).unwrap();
        // Pure index permutation: exact.
        assert_eq!(lag, arr2(&case["lag"]), "recurrence_to_lag pad={pad}");
        assert_eq!(
            lag_to_recurrence(lag.view()).unwrap(),
            rec,
            "round trip pad={pad}"
        );
    }
}

#[test]
fn sync_matches_librosa() {
    let f = fixture();
    let data = arr2(&f["sync_input"]);
    for (name, case) in f["sync"].as_object().unwrap() {
        let idx = usize_vec(&case["idx"]);
        let pad = case["pad"].as_bool().unwrap();
        let agg = match case["aggregate"].as_str().unwrap() {
            "mean" => SyncAggregate::Mean,
            "median" => SyncAggregate::Median,
            "max" => SyncAggregate::Max,
            "min" => SyncAggregate::Min,
            "sum" => SyncAggregate::Sum,
            a => panic!("unknown aggregate {a}"),
        };
        let r = sync(data.view(), &idx, agg, pad).unwrap();
        if idx.is_empty() {
            // Documented difference: librosa treats an empty index list as an
            // empty list of slices (0 output columns); we pad it to the single
            // segment [0, n_frames).
            assert_eq!(arr2(&case["out"]).ncols(), 0);
            assert_eq!(r.ncols(), 1, "sync/{name}");
            continue;
        }
        // numpy's pairwise summation vs our sequential sum over <= 20 values.
        assert_close(&format!("sync/{name}"), &r, &arr2(&case["out"]), 1e-15, 0.0);
    }
}
